/// Which temporal value a temporal input picks.
enum DtxTemporalKind { date, time, dateTime }

String _pad(int value, int width) => value.toString().padLeft(width, '0');

/// A date-only wire value as a calendar day in the user's own time zone.
DateTime dtxCalendarDate(String value) {
  final parts = value.split('-');
  if (parts.length == 3 && value.length == 10) {
    return DateTime(int.parse(parts[0]), int.parse(parts[1]), int.parse(parts[2]));
  }
  return DateTime.parse(value).toLocal();
}

/// `date`/`time`/`dateTime(label?) : bind(member)?`: the value in the
/// session locale's format, changed through the platform's pickers.
class DtxTemporalInput extends StatefulWidget {
  const DtxTemporalInput({super.key, required this.kind, this.label, this.value, this.onChanged, this.onChange, this.style});

  final DtxTemporalKind kind;
  final String? label;
  final String? value;
  final ValueChanged<String>? onChanged;
  final VoidCallback? onChange;
  final DtxStyle? style;

  @override
  State<DtxTemporalInput> createState() => _DtxTemporalInputState();
}

class _DtxTemporalInputState extends State<DtxTemporalInput> {
  late String? _value = widget.value;

  @override
  void didUpdateWidget(DtxTemporalInput oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.value != null) {
      _value = widget.value;
    }
  }

  DateTime _current() {
    final value = _value;
    if (value == null || value.isEmpty) {
      return DateTime.now();
    }
    if (widget.kind == DtxTemporalKind.time) {
      final parts = value.split(':');
      final now = DateTime.now();
      return DateTime(now.year, now.month, now.day, int.parse(parts[0]), int.parse(parts[1]));
    }
    return dtxCalendarDate(value);
  }

  String _shown() {
    final value = _value;
    if (value == null || value.isEmpty) {
      return '';
    }
    final locale = datrixRuntime.session.locale;
    final current = _current();
    return switch (widget.kind) {
      DtxTemporalKind.date => formatDate(current, locale),
      DtxTemporalKind.time => formatTime(current, locale),
      DtxTemporalKind.dateTime => '${formatDate(current, locale)} ${formatTime(current, locale)}',
    };
  }

  Future<DateTime?> _pickDate(DateTime current) {
    return showDatePicker(context: context, initialDate: current, firstDate: DateTime(current.year - 100), lastDate: DateTime(current.year + 100));
  }

  Future<void> _pick() async {
    final current = _current();
    final date = widget.kind == DtxTemporalKind.time ? current : await _pickDate(current);
    if (date == null || !mounted) {
      return;
    }
    if (widget.kind == DtxTemporalKind.date) {
      return _write('${_pad(date.year, 4)}-${_pad(date.month, 2)}-${_pad(date.day, 2)}');
    }
    final time = await showTimePicker(context: context, initialTime: TimeOfDay.fromDateTime(current));
    if (time == null || !mounted) {
      return;
    }
    if (widget.kind == DtxTemporalKind.time) {
      return _write('${_pad(time.hour, 2)}:${_pad(time.minute, 2)}:00');
    }
    _write(DateTime(date.year, date.month, date.day, time.hour, time.minute).toUtc().toIso8601String());
  }

  void _write(String value) {
    setState(() => _value = value);
    widget.onChanged?.call(value);
    widget.onChange?.call();
  }

  @override
  Widget build(BuildContext context) {
    final icon = widget.kind == DtxTemporalKind.time ? Icons.schedule : Icons.calendar_today;
    final field = InkWell(
      onTap: _pick,
      child: InputDecorator(
        decoration: InputDecoration(labelText: widget.label, suffixIcon: Icon(icon)),
        child: Text(_shown()),
      ),
    );
    return dtxStyled(context, widget.style, Semantics(button: true, child: field));
  }
}

