        ? slider
        : Semantics(
            label: label,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                ExcludeSemantics(child: Text(label)),
                slider,
              ],
            ),
          );
    return dtxStyled(context, widget.style, labelled);
  }
}

